'use client'

import { useEffect, useId, useRef, type ReactNode } from 'react'
import './scroll-expand-hero.css'

export interface ScrollExpandHeroProps {
  eyebrow?: string
  title: string
  description?: string
  /** Decorative artwork only. Keep meaningful information in the text props. */
  media: ReactNode
  action?: { label: string; href: string }
  caption?: string
  className?: string
}

function nearestViewport(element: HTMLElement): HTMLElement | null {
  let parent = element.parentElement
  while (parent && parent !== document.documentElement) {
    const overflow = window.getComputedStyle(parent).overflowY
    if (/(auto|scroll|overlay)/.test(overflow) && parent.scrollHeight > parent.clientHeight + 1) return parent
    parent = parent.parentElement
  }
  return null
}

function decorativeMedia(element: HTMLDivElement | null) {
  element?.setAttribute('inert', '')
}

/** A bounded, native-scroll hero whose framed image grows into the whole scene. */
export function ScrollExpandHero({
  eyebrow,
  title,
  description,
  media,
  action,
  caption,
  className = '',
}: ScrollExpandHeroProps) {
  const headingId = useId()
  const rootRef = useRef<HTMLElement>(null)
  const pinRef = useRef<HTMLDivElement>(null)
  const copyRef = useRef<HTMLElement>(null)
  const captionRef = useRef<HTMLParagraphElement>(null)

  useEffect(() => {
    const root = rootRef.current
    const pin = pinRef.current
    const copy = copyRef.current
    if (!root || !pin || !copy) return
    const reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)')
    let frame = 0
    let previousHeight = 0

    function readPosition() {
      frame = 0
      if (!root || !pin || !copy) return
      const viewport = nearestViewport(root)
      const viewportTop = viewport ? viewport.getBoundingClientRect().top + viewport.clientTop : 0
      const height = viewport?.clientHeight || window.innerHeight
      if (height !== previousHeight) {
        previousHeight = height
        root.style.setProperty('--ac-scroll-expand-view', `${height}px`)
      }
      const pinStyle = window.getComputedStyle(pin)
      const gap = Number.parseFloat(pinStyle.rowGap) || 20
      const bottomPadding = Number.parseFloat(pinStyle.paddingBottom) || 17
      const startTop = copy.offsetTop + copy.offsetHeight + gap
      const startBottom = bottomPadding + (captionRef.current ? captionRef.current.offsetHeight + gap : 0)
      // Longer copy gets enough scene height to remain readable rather than clipping.
      const contentHeight = Math.ceil(startTop + startBottom + 100)
      root.style.setProperty('--ac-scroll-expand-content-height', `${contentHeight}px`)
      root.style.setProperty('--ac-scroll-expand-start-top', `${startTop}px`)
      root.style.setProperty('--ac-scroll-expand-start-bottom', `${startBottom}px`)
      const bounds = root.getBoundingClientRect()
      const travel = Math.max(1, bounds.height - height)
      const progress = reducedMotion.matches ? 1 : Math.min(1, Math.max(0, (viewportTop - bounds.top) / travel))
      root.style.setProperty('--ac-scroll-expand-progress', progress.toFixed(4))
    }

    function scheduleRead() {
      if (!frame) frame = window.requestAnimationFrame(readPosition)
    }

    // Capturing scroll events also covers nested overflow containers.
    document.addEventListener('scroll', scheduleRead, { capture: true, passive: true })
    window.addEventListener('scroll', scheduleRead, { passive: true })
    window.addEventListener('resize', scheduleRead)
    reducedMotion.addEventListener('change', scheduleRead)
    const resize = typeof ResizeObserver === 'undefined' ? null : new ResizeObserver(scheduleRead)
    let ancestor: HTMLElement | null = root
    while (ancestor && ancestor !== document.documentElement) {
      resize?.observe(ancestor)
      ancestor = ancestor.parentElement
    }
    resize?.observe(pin)
    resize?.observe(copy)
    if (captionRef.current) resize?.observe(captionRef.current)
    readPosition()

    return () => {
      document.removeEventListener('scroll', scheduleRead, true)
      window.removeEventListener('scroll', scheduleRead)
      window.removeEventListener('resize', scheduleRead)
      reducedMotion.removeEventListener('change', scheduleRead)
      resize?.disconnect()
      window.cancelAnimationFrame(frame)
      root.style.removeProperty('--ac-scroll-expand-view')
      root.style.removeProperty('--ac-scroll-expand-progress')
      root.style.removeProperty('--ac-scroll-expand-content-height')
      root.style.removeProperty('--ac-scroll-expand-start-top')
      root.style.removeProperty('--ac-scroll-expand-start-bottom')
    }
  }, [title, description, eyebrow, action?.label, caption])

  return (
    <section ref={rootRef} className={`ac-scroll-expand-hero ${className}`.trim()} aria-labelledby={headingId}>
      <div ref={pinRef} className="ac-scroll-expand-pin">
        <header ref={copyRef} className="ac-scroll-expand-copy">
          {eyebrow && <p className="ac-scroll-expand-eyebrow">{eyebrow}</p>}
          <h2 id={headingId}>{title}</h2>
          {description && <p className="ac-scroll-expand-description">{description}</p>}
          {action && <a className="ac-scroll-expand-action" href={action.href}>{action.label}<span aria-hidden="true">↗</span></a>}
        </header>
        <div ref={decorativeMedia} className="ac-scroll-expand-media" aria-hidden="true">{media}</div>
        {caption && <p ref={captionRef} className="ac-scroll-expand-caption">{caption}</p>}
      </div>
    </section>
  )
}

.ac-scroll-expand-hero {
  --ac-scroll-expand-progress: 0;
  --ac-scroll-expand-view: 800px;
  --ac-scroll-expand-paper: #18382e;
  --ac-scroll-expand-ink: #f3f0e5;
  --ac-scroll-expand-muted: #d3ddd0;
  --ac-scroll-expand-start-top: 310px;
  --ac-scroll-expand-start-bottom: 50px;
  --ac-scroll-expand-content-height: 0px;
  --ac-scroll-expand-pin-height: max(440px, calc(var(--ac-scroll-expand-view) * .96), var(--ac-scroll-expand-content-height));
  position: relative;
  min-height: calc(var(--ac-scroll-expand-pin-height) + var(--ac-scroll-expand-view) * .85);
  background: var(--ac-scroll-expand-paper);
  color: var(--ac-scroll-expand-ink);
  font-family: inherit;
  container-type: inline-size;
  isolation: isolate;
}

.ac-scroll-expand-hero * { box-sizing: border-box; }

.ac-scroll-expand-pin {
  position: sticky;
  top: 0;
  display: block;
  gap: clamp(18px, 3cqw, 40px);
  height: var(--ac-scroll-expand-pin-height);
  padding-top: clamp(25px, 5cqw, 64px);
  padding-bottom: 17px;
}

.ac-scroll-expand-copy {
  position: relative;
  z-index: 2;
  padding-inline: clamp(20px, 5cqw, 72px);
  text-align: center;
  transform: translateY(calc(var(--ac-scroll-expand-progress) * -14px));
}

.ac-scroll-expand-eyebrow {
  margin: 0 0 17px;
  font-size: 10px;
  font-weight: 500;
  line-height: 1.4;
  letter-spacing: .15em;
  text-transform: uppercase;
}

.ac-scroll-expand-copy h2 {
  max-width: 14ch;
  margin: 0 auto;
  font-family: var(--ac-scroll-expand-heading-font, Georgia, serif);
  font-size: clamp(42px, 9.8cqw, 138px);
  font-weight: 400;
  line-height: .93;
  letter-spacing: -.065em;
  white-space: pre-line;
  overflow-wrap: anywhere;
}

.ac-scroll-expand-description {
  max-width: 42ch;
  margin: 19px auto 0;
  color: var(--ac-scroll-expand-muted);
  font-size: clamp(12px, 1.25cqw, 16px);
  line-height: 1.55;
  text-wrap: pretty;
}

.ac-scroll-expand-action {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 25px;
  min-height: 44px;
  margin-top: 20px;
  padding: 10px 19px;
  border: 1px solid currentColor;
  border-radius: 999px;
  color: inherit;
  font-size: 12px;
  line-height: 1.4;
  text-decoration: none;
  transition: background-color 180ms ease, color 180ms ease;
}

.ac-scroll-expand-action:hover { background: var(--ac-scroll-expand-ink); color: var(--ac-scroll-expand-paper); }
.ac-scroll-expand-action:focus-visible { outline: 2px solid currentColor; outline-offset: 5px; }
.ac-scroll-expand-action span { font-size: 17px; }

.ac-scroll-expand-media {
  position: absolute;
  z-index: 0;
  top: calc(var(--ac-scroll-expand-start-top) * (1 - var(--ac-scroll-expand-progress)));
  bottom: calc(var(--ac-scroll-expand-start-bottom) * (1 - var(--ac-scroll-expand-progress)));
  left: 50%;
  width: calc(68% + var(--ac-scroll-expand-progress) * 32%);
  min-height: 0;
  overflow: hidden;
  border-radius: calc((1 - var(--ac-scroll-expand-progress)) * 28px);
  background: #29483b;
  transform: translateX(-50%);
}

.ac-scroll-expand-media::after {
  position: absolute;
  inset: 0;
  content: '';
  background: linear-gradient(180deg, #0c2018cc 0%, #0c2018b3 43%, #0c20182e 75%, #0c201880 100%);
  pointer-events: none;
}

.ac-scroll-expand-media > * { display: block; width: 100%; height: 100%; }
.ac-scroll-expand-media img, .ac-scroll-expand-media video { object-fit: cover; }

.ac-scroll-expand-caption {
  position: absolute;
  z-index: 2;
  right: 0;
  bottom: 17px;
  left: 0;
  margin: 0;
  padding-inline: 20px;
  color: var(--ac-scroll-expand-muted);
  font-size: 9px;
  line-height: 1.5;
  letter-spacing: .08em;
  text-align: center;
}

@container (max-width: 520px) {
  .ac-scroll-expand-pin { gap: 19px; padding-top: 25px; }
  .ac-scroll-expand-eyebrow { margin-bottom: 14px; font-size: 8px; }
  .ac-scroll-expand-description { margin-top: 14px; }
  .ac-scroll-expand-action { margin-top: 15px; font-size: 11px; }
}

@media (prefers-reduced-motion: reduce) {
  .ac-scroll-expand-hero { min-height: 0; }
  .ac-scroll-expand-pin { position: relative; height: auto; min-height: max(440px, var(--ac-scroll-expand-content-height)); padding-bottom: 220px; }
  .ac-scroll-expand-copy { transform: none; }
  .ac-scroll-expand-media { top: 0; bottom: 0; width: 100%; border-radius: 0; }
  .ac-scroll-expand-action { transition: none; }
}
